  background: var(--color-white); color: var(--primary-6); font-weight: var(--font-weight-medium);
  border-left: 1px solid var(--color-border-2); border-right: 1px solid var(--color-border-2);
  border-top: none; border-bottom: 1px solid var(--color-white);
  box-shadow: inset 0 2px 0 0 var(--primary-6);
}

.tabs-capsule {
  display: inline-flex; align-items: center; gap: 4px; padding: 3px;
  background: var(--color-bg-5); border-radius: var(--radius-full);
  width: fit-content;
}

.tabs-capsule .tab-item {
  padding: 4px 14px; border: none; border-radius: var(--radius-full); background: transparent;
  color: var(--color-text-2); font-size: var(--font-size-lead);
  font-weight: var(--font-weight-regular); line-height: var(--line-height-h4); cursor: pointer;
  transition: all 150ms ease; white-space: nowrap;
}

.tabs-capsule .tab-item.active {
  background: var(--primary-6); color: var(--primary-foreground);
  font-weight: var(--font-weight-medium);
  box-shadow: 0px 1px 3px rgba(22, 100, 255, 0.3);
}

.tabs-button {
  display: inline-flex; align-items: center; border: 1px solid var(--color-border-3);
  border-radius: var(--radius-sm); background: var(--color-bg-4); padding: 2px; gap: 0;
  width: fit-content;
}

.tabs-button .tab-item {
  padding: 4px 14px; border: none; border-radius: 3px; background: transparent;
  color: var(--color-text-2); font-size: var(--font-size-lead);
  font-weight: var(--font-weight-regular); line-height: var(--line-height-h4); cursor: pointer;
  transition: all 150ms ease; white-space: nowrap;
}

.tabs-button .tab-item.active {
  background: var(--color-white); color: var(--primary-6); font-weight: var(--font-weight-medium);
  box-shadow: 0px 1px 2px rgba(0,0,0,0.07), 0px 0.5px 1px rgba(0,0,0,0.05);
}

.othertabs {
  display: inline-flex; align-items: center; gap: 2px; padding: 3px;
  background: rgba(199, 204, 214, 0.3); border-radius: var(--radius-sm);
  width: fit-content;
}

.othertabs-item {
  padding: 2px 12px; border: none; border-radius: 2px; background: transparent;
  color: var(--color-text-2); font-size: var(--font-size-lead);
  font-weight: var(--font-weight-regular); line-height: var(--line-height-h4); cursor: pointer;
  transition: all 0.15s;
}

.othertabs-item.active {
  background: var(--color-white); color: var(--primary-6); font-weight: var(--font-weight-medium);
  border-radius: var(--radius-sm);
  box-shadow: 0px 1px 2px 0px rgba(0,0,0,0.07), 0px 0.5px 1px 0px rgba(0,0,0,0.05), 0px 0px 0px 0.5px rgba(213,219,227,0.7);
}

.tabs-wrapper {
  display: flex; align-items: center;
  justify-content: space-between; border-bottom: 1px solid var(--color-border-2);
}

.tabs-extra {
  display: flex; align-items: center;
  gap: var(--space-2); padding-right: 16px;
}

.tabs-extra .btn-extra {
  display: inline-flex; align-items: center; justify-content: center; height: 28px; padding: 0 12px;
  border: 1px solid var(--color-border-3); border-radius: var(--radius-sm);
  background: var(--color-white); color: var(--color-text-2); font-size: var(--font-size-lead);
  cursor: pointer; transition: all 150ms ease; gap: var(--space-1);
}

.tabs-add-btn {
  display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px;
  border: 1px solid var(--color-border-3); border-radius: var(--radius-sm);
  background: var(--color-white); color: var(--color-text-2); font-size: var(--font-size-h3);
  cursor: pointer; transition: all 150ms ease; margin-left: var(--space-2);
}

.tab-panel {
  padding: 16px 0; font-size: var(--font-size-lead);
  color: var(--color-text-2); line-height: var(--line-height-h4);
}

.tab-panel-bordered {
  border: 1px solid var(--color-border-2); border-top: none;
  padding: var(--space-4); border-radius: 0 0 4px 4px;
}

.timepicker-input {
  display: inline-flex; align-items: center; width: 100%; background: var(--color-white);
  border: 1px solid var(--color-border-3); border-radius: var(--radius-sm);
  font-weight: var(--font-weight-regular);
  cursor: pointer; transition: border-color 150ms ease, background-color 150ms ease;
}

.timepicker-suffix {
  display: inline-flex; align-items: center; margin-left: auto;
  padding-left: 8px; color: var(--color-text-3);
}

.timepicker.disabled .timepicker-input {
  background: var(--color-bg-4); border-color: var(--color-border-3);
  cursor: not-allowed;
}

.tooltip {
  display: inline-flex; position: relative; color: var(--color-white);
  font-size: var(--font-size-body); font-weight: var(--font-weight-regular);
  line-height: var(--line-height-body);
}

.tooltip-bubble {
  display: inline-flex; align-items: center; justify-content: center; overflow: hidden;
  padding: 6px 8px; border-radius: var(--radius-sm); background: var(--grey-8);
  box-shadow: 0 5px 15px rgba(0,0,0,0.05), 0 15px 35px rgba(0,0,0,0.05); white-space: nowrap;
}

.top-nav {
  height: 48px; background: var(--bg-white); display: flex; align-items: center;
  box-shadow: 0 2px 6px 0 rgba(0, 0, 0, 0.05); position: relative; z-index: 100; width: 100%;
  flex-shrink: 0;
}

.product-tabs {
  display: flex; align-items: center; margin-left: var(--space-8); padding-left: 24px;
  gap: var(--space-6); height: 100%;
}

.product-tab {
  font-size: var(--font-size-lead); color: var(--text-2); cursor: pointer; height: 100%;
  display: flex; align-items: center; position: relative; white-space: nowrap;
  font-weight: var(--font-weight-regular);
}

.product-tab.active::after {
  content: ''; position: absolute; bottom: 0; left: 0; right: 0; height: 2px;
  background: var(--primary-6);
}

.nav-right {
  margin-left: auto; display: flex; align-items: center;
  gap: var(--space-4); padding-right: 16px;
}

.status-tag {
  display: inline-flex; align-items: center; gap: var(--space-1); border: none;
  border-radius: var(--radius-sm); font-size: var(--font-size-body);
  line-height: var(--line-height-body); font-weight: var(--font-weight-medium); white-space: nowrap;
  box-sizing: border-box;

}

.status-tag-icon {
  flex-shrink: 0; width: 14px; height: 14px; display: inline-flex; align-items: center;
  justify-content: center;
}

@media (max-width: 760px) {
  .yl-desktop-navigation { display: none; }
  .yl-mobile-toggle.btn { display: inline-flex; }
  .yl-shell-topnav { padding: 8px 16px; flex-wrap: wrap; }
  .yl-shell-identity { flex: 1 1 0%; }
  .yl-shell-content { padding: 20px 16px; }
  .yl-list-header.page-header-comp { flex-direction: column; }
  .yl-filters .ui-input { max-width: 100%; }
}

:root {
  color-scheme: light;
  --font-sans: var(--font-family-base);
  --yuanli-color-sidebar: var(--color-sidebar);
  --grey-1: var(--text-yuanliNeutral-1);
  --grey-2: var(--text-yuanliNeutral-2);
  --grey-3: var(--text-yuanliNeutral-3);
  --grey-4: var(--text-yuanliNeutral-6);
  --grey-5: #676b72;
  --grey-6: var(--text-yuanliNeutral-7);
  --grey-7: var(--text-yuanliNeutral-9);
  --grey-8: var(--text-yuanliNeutral-8);
}
